    // Serving read queries locally because the node *believes* it is the leader
    fn serve_read_vulnerable(&self, key: &str) -> Option<String> {
        if self.is_leader {
            // BUG: During a network partition, we might have been deposed!
            // Another leader is elected, but we can't hear the heartbeat.
            // Serving from local cache returns stale, non-linearizable data.
            self.local_cache.get(key).cloned()
        } else {
            None
        }
    }
}
